CREATE TABLE public.generated_images (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, prompt text NOT NULL, image_data text NOT NULL, created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT, INSERT, DELETE ON public.generated_images TO authenticated; GRANT ALL ON public.generated_images TO service_role; ALTER TABLE public.generated_images ENABLE ROW LEVEL SECURITY; CREATE POLICY images_select ON public.generated_images FOR SELECT TO authenticated USING (auth.uid() = user_id); CREATE POLICY images_insert ON public.generated_images FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id); CREATE POLICY images_delete ON public.generated_images FOR DELETE TO authenticated USING (auth.uid() = user_id); CREATE TABLE public.ai_service_state (service text PRIMARY KEY, reason text NOT NULL, status integer NOT NULL, paused_at timestamptz NOT NULL DEFAULT now()); GRANT ALL ON public.ai_service_state TO service_role; ALTER TABLE public.ai_service_state ENABLE ROW LEVEL SECURITY;